export const arithmeticLabels=Object.freeze({
 exact:"Exact / symbolic",numeric:"Numerical computation",mixed:"Mixed / mode-dependent",reference:"Catalogue lookup and validation"
});
export const arithmeticDescriptions=Object.freeze({
 exact:"Uses integers, rational numbers, or symbolic expressions under the stated input and algorithm conditions. Read each tool's result for its scope and completeness conditions.",
 numeric:"Uses floating-point arithmetic, sampling, or numerical linear algebra. Assess precision using tolerances, residuals, and convergence checks.",
 mixed:"Combines exact constructions with numerical responses, or provides selectable calculation modes. See the scope for the distinction.",
 reference:"Retrieves recorded classification data and performs the relevant checks on the selected input. Catalogue counts and complete representative lists are reported separately."
});
